package dev.veltraph.client.observation.nativeinput;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
/** Identity mechanics only. These tests do not manufacture native constructor authority. */
final class NativeKeyBindingOrderTest {
 @Test void genuineInitialHistoryIsCurrent(){var order=new NativeKeyBindingOrder();var before=order.snapshot();assertNotNull(before);assertTrue(order.current(before));}
 @Test void aWriteInvalidatesBeforeEvenBeforeReturning(){var order=new NativeKeyBindingOrder();var before=order.snapshot();order.attempt();assertFalse(order.current(before));assertNull(order.snapshot());}
 @Test void normalReturnProducesDistinctAttempt(){var order=new NativeKeyBindingOrder();var before=order.snapshot();var write=order.attempt();order.returned(write,true);assertSame(write,order.snapshot());assertFalse(order.current(before));}
 @Test void sameValueStillInvalidatesTheOriginalAttempt(){var order=new NativeKeyBindingOrder();var before=order.snapshot();var sameValueAttempt=order.attempt();order.returned(sameValueAttempt,true);assertFalse(order.current(before));assertTrue(order.current(sameValueAttempt));}
 @Test void abaNeverReturnsTheOriginalToken(){var order=new NativeKeyBindingOrder();var before=order.snapshot();var away=order.attempt();order.returned(away,true);var back=order.attempt();order.returned(back,true);assertFalse(order.current(before));assertFalse(order.current(away));assertTrue(order.current(back));}
 @Test void failedFieldDoesNotExposeNormalHistory(){var order=new NativeKeyBindingOrder();var before=order.snapshot();var write=order.attempt();order.returned(write,false);assertNull(order.snapshot());assertFalse(order.current(before));assertFalse(order.current(write));}
 @Test void overlappingNormalReturnsRemainUnknown(){var order=new NativeKeyBindingOrder();var outer=order.attempt();var inner=order.attempt();order.returned(inner,true);assertNull(order.snapshot());order.returned(outer,true);assertNull(order.snapshot());assertFalse(order.current(outer));assertFalse(order.current(inner));}
 @Test void outerFirstCompletionAlsoRemainsUnknown(){var order=new NativeKeyBindingOrder();var outer=order.attempt();var inner=order.attempt();order.returned(outer,true);assertNull(order.snapshot());order.returned(inner,true);assertNull(order.snapshot());assertFalse(order.current(inner));}
 @Test void concurrentOverlapRemainsUnknown() throws InterruptedException {var order=new NativeKeyBindingOrder();var outer=order.attempt();var completed=new java.util.concurrent.CountDownLatch(1);var innerToken=new java.util.concurrent.atomic.AtomicReference<Object>();var thread=new Thread(()->{var inner=order.attempt();innerToken.set(inner);order.returned(inner,true);completed.countDown();},"binding-order-overlap-negative");thread.start();assertTrue(completed.await(2,java.util.concurrent.TimeUnit.SECONDS));assertNull(order.snapshot());order.returned(outer,true);thread.join(2000);assertFalse(thread.isAlive());assertNull(order.snapshot());assertFalse(order.current(innerToken.get()));}
 @Test void outerFailureCannotExposeAnInnerNormalReturn(){var order=new NativeKeyBindingOrder();var outer=order.attempt();var inner=order.attempt();order.returned(inner,true);order.returned(outer,false);assertNull(order.snapshot());assertFalse(order.current(inner));}
 @Test void freshNonoverlappingObservationNeverRestoresTheOldHistory(){var order=new NativeKeyBindingOrder();var before=order.snapshot();var outer=order.attempt();var inner=order.attempt();order.returned(inner,true);order.returned(outer,true);var fresh=order.attempt();order.returned(fresh,true);assertSame(fresh,order.snapshot());assertFalse(order.current(before));assertFalse(order.current(outer));assertFalse(order.current(inner));}
 @Test void anotherKeyCannotBorrowAttemptIdentity(){var first=new NativeKeyBindingOrder();var second=new NativeKeyBindingOrder();assertFalse(second.current(first.snapshot()));}
 @Test void unknownOrRepeatedCompletionCannotChangeHistory(){var order=new NativeKeyBindingOrder();var write=order.attempt();order.returned(new Object(),true);assertNull(order.snapshot());order.returned(write,false);order.returned(write,true);assertNull(order.snapshot());assertFalse(order.current(write));}
}
